141	        this.clinicService.saveOwner(owner);
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
160	        normalizeEmail(ownerFieldsDto);
161	        currentOwner.setEmail(ownerFieldsDto.getEmail());
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        HttpHeaders headers = new HttpHeaders();
186	        Pet pet = petMapper.toPet(petFieldsDto);
187	        owner.setId(ownerId);
188	        pet.setOwner(owner);
189	        pet.getType().setName(null);
190	        this.clinicService.savePet(pet);
191	        PetDto petDto = petMapper.toPetDto(pet);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
193	            .buildAndExpand(pet.getId()).toUri());
194	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner != null) {
202	            Pet currentPet = this.clinicService.findPetById(petId);
203	            if (currentPet != null) {
204	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
205	                currentPet.setName(petFieldsDto.getName());
206	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
207	                this.clinicService.savePet(currentPet);
208	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
209	            }
210	        }
211	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
217	        HttpHeaders headers = new HttpHeaders();
218	        Visit visit = visitMapper.toVisit(visitFieldsDto);
219	        Pet pet = new Pet();
220	        pet.setId(petId);
221	        visit.setPet(pet);
222	        this.clinicService.saveVisit(visit);
223	        VisitDto visitDto = visitMapper.toVisitDto(visit);
224	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
225	            .buildAndExpand(visit.getId()).toUri());
226	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
227	    }
228	
229	
230	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
231	    @Override
232	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
233	        Owner owner = this.clinicService.findOwnerById(ownerId);
234	        if (owner != null) {
235	            Pet pet = owner.getPet(petId);
236	            if (pet != null) {
237	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
238	            }
239	        }
240	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	    }
242	
243	    /**
244	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
245	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
246	     * does not catch). The names of all offending fields are collected so the caller receives a
247	     * 400 response whose {@code errors} array lists each one.
248	     */
249	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
250	        List<String> missingFields = new ArrayList<>();
251	        if (isBlank(ownerFieldsDto.getFirstName())) {
252	            missingFields.add("firstName");
253	        }
254	        if (isBlank(ownerFieldsDto.getLastName())) {
255	            missingFields.add("lastName");
256	        }
257	        if (isBlank(ownerFieldsDto.getAddress())) {
258	            missingFields.add("address");
259	        }
260	        if (isBlank(ownerFieldsDto.getCity())) {
261	            missingFields.add("city");
262	        }
263	        if (isBlank(ownerFieldsDto.getTelephone())) {
264	            missingFields.add("telephone");
265	        }
266	        if (!missingFields.isEmpty()) {
267	            throw new InvalidOwnerFieldsException(missingFields);
268	        }
269	    }
270	
271	    private static boolean isBlank(String value) {
272	        return value == null || value.trim().isEmpty();
273	    }
274	
275	    /**
276	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
277	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
278	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
279	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
280	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
281	     * means an address that is blank after normalization is rejected like a missing one.
282	     */
283	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
284	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
285	    }
286	
287	    /**
288	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
289	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
290	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
291	     * address is returned unchanged, making it safe to apply to stored values during comparison.
292	     */
293	    private static String canonicalAddress(String address) {
294	        if (address == null) {
295	            return null;
296	        }
297	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
298	        if (collapsed.isEmpty()) {
299	            return "";
300	        }
301	        String[] tokens = collapsed.split(" ");
302	        StringBuilder sb = new StringBuilder(collapsed.length());
303	        for (int i = 0; i < tokens.length; i++) {
304	            if (i > 0) {
305	                sb.append(' ');
306	            }
307	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
308	        }
309	        return sb.toString();
310	    }
311	
312	    /**
313	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
314	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
315	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
316	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
317	     * string is written back onto the request so it is what gets stored and returned. Any value that
318	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
319	     * names {@code telephone}.
320	     */
321	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
322	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
323	    }
324	
325	    /**
326	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
327	     * (400) naming {@code telephone} when it cannot form a valid number.
328	     */
329	    private static String toE164(String telephone) {
330	        if (telephone == null) {
331	            throw new InvalidOwnerFieldsException(List.of("telephone"));
332	        }
333	        boolean hasCountryCode = telephone.trim().startsWith("+");
334	        String digits = telephone.replaceAll("\\D", "");
335	        String national;
336	        if (hasCountryCode) {
337	            national = digits;
338	        } else {
339	            if (digits.startsWith("0")) {
340	                digits = digits.substring(1);
341	            }
342	            national = "61" + digits;
343	        }
344	        if (!national.matches("[0-9]{8,15}")) {
345	            throw new InvalidOwnerFieldsException(List.of("telephone"));
346	        }
347	        return "+" + national;
348	    }
349	
350	    /**
351	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
352	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
353	     * each existing owner's stored telephone is converted the same way before comparison so numbers
354	     * that only differ in formatting still collide. A match results in a 409 response naming
355	     * {@code telephone}.
356	     */
357	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
358	        String telephone = ownerFieldsDto.getTelephone();
359	        for (Owner existing : this.clinicService.findAllOwners()) {
360	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
361	                throw new DuplicateOwnerTelephoneException(telephone);
362	            }
363	        }
364	    }
365	
366	    /**
367	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
368	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
369	     */
370	    private static String normalizeExisting(String telephone) {
371	        try {
372	            return toE164(telephone);
373	        } catch (InvalidOwnerFieldsException ex) {
374	            return null;
375	        }
376	    }
377	
378	    /**
379	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
380	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
381	     * single space, so values that differ only in letter case or spacing still collide. When the
382	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
383	     * household members to share a name and address. A match results in a 409 response naming
384	     * {@code lastName} and {@code address}.
385	     */
386	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
387	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
388	            return;
389	        }
390	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
391	        String address = canonicalAddress(ownerFieldsDto.getAddress());
392	        for (Owner existing : this.clinicService.findAllOwners()) {
393	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
394	                && address.equals(canonicalAddress(existing.getAddress()))) {
395	                throw new DuplicateOwnerHouseholdException(
396	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
397	            }
398	        }
399	    }
400	
401	    /**
402	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
403	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
404	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
405	     */
406	    private static String normalizeForComparison(String value) {
407	        if (value == null) {
408	            return "";
409	        }
410	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
411	    }
412	
413	    /**
414	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
415	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
416	     * written back onto the request so that is what gets stored and returned. A present but invalid
417	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
418	     */
419	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
420	        String email = ownerFieldsDto.getEmail();
421	        if (email == null) {
422	            return;
423	        }
424	        String trimmed = email.trim();
425	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
426	            throw new InvalidOwnerFieldsException(List.of("email"));
427	        }
428	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
429	    }
430	
431	    /**
432	     * Defaults an owner's {@code registrationDate} on create. When the caller supplies no value,
433	     * it is set to the server's current date so every owner is persisted with a registration date;
434	     * a value provided in the request is kept as-is. The date is stored and returned in ISO
435	     * {@code YYYY-MM-DD} format.
436	     */
437	    private void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
438	        if (ownerFieldsDto.getRegistrationDate() == null) {
439	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
440	        }
441	    }
442	
443	    /**
444	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
445	     * {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN} is a
446	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
447	     * (e.g. {@code 'SMI-0007'}).
448	     */
449	    private void assignCustomerCode(Owner owner) {
450	        String lastName = owner.getLastName();
451	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
452	        int sequence = this.clinicService.findAllOwners().size() + 1;
453	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
454	    }
455	
456	    /**
457	     * Assigns the owner's {@code membershipNumber} on create, formatted
458	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
459	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}). Assigned after
460	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
461	     * inputs are present.
462	     */
463	    private void assignMembershipNumber(Owner owner) {
464	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
465	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
466	    }
467	
468	    /**
469	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
470	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
471	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
472	     */
473	    private void assignNamesakeCount(Owner owner) {
474	        String firstName = owner.getFirstName();
475	        String lastName = owner.getLastName();
476	        int count = 0;
477	        for (Owner existing : this.clinicService.findAllOwners()) {
478	            if (firstName.equalsIgnoreCase(existing.getFirstName())
479	                && lastName.equalsIgnoreCase(existing.getLastName())) {
480	                count++;
481	            }
482	        }
483	        owner.setNamesakeCount(count);
484	    }
485	
486	    /**
487	     * Assigns the new owner's {@code householdId} when the request opts in with
488	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
489	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
490	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
491	     * all end up carrying one stable shared identifier: if any existing member already has a
492	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
493	     * and address. Any existing member that is missing the identifier is updated so the whole
494	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
495	     * identifier is assigned.
496	     */
497	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
498	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
499	            return;
500	        }
501	        String lastName = normalizeForComparison(owner.getLastName());
502	        String address = canonicalAddress(owner.getAddress());
503	        List<Owner> members = new ArrayList<>();
504	        for (Owner existing : this.clinicService.findAllOwners()) {
505	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
506	                && address.equals(canonicalAddress(existing.getAddress()))) {
507	                members.add(existing);
508	            }
509	        }
510	        if (members.isEmpty()) {
511	            return;
512	        }
513	        String householdId = members.stream()
514	            .map(Owner::getHouseholdId)
515	            .filter(id -> id != null && !id.isBlank())
516	            .findFirst()
517	            .orElseGet(() -> newHouseholdId(lastName, address));
518	        owner.setHouseholdId(householdId);
519	        for (Owner member : members) {
520	            if (!householdId.equals(member.getHouseholdId())) {
521	                member.setHouseholdId(householdId);
522	                this.clinicService.saveOwner(member);
523	            }
524	        }
525	    }
526	
527	    /**
528	     * Derives a stable household identifier from the normalized last name and address: the first
529	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
530	     * owners in the same household therefore derive the same value regardless of creation order.
531	     */
532	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
533	        try {
534	            byte[] digest = MessageDigest.getInstance("SHA-256")
535	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
536	            StringBuilder hex = new StringBuilder(digest.length * 2);
537	            for (byte b : digest) {
538	                hex.append(String.format("%02x", b));
539	            }
540	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
541	        } catch (NoSuchAlgorithmException ex) {
542	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
543	        }
544	    }
545	}
